#include "shared/sea_nuclear_wave.hpp"
#include <algorithm>
#include <cmath>
#include <cstdio>
#include <vector>
using namespace std;
static SeaNuclearWaveSample exact(const vector<SeaNuclearWave>&w,float x,float z){SeaNuclearWaveSample r;for(auto&a:w){auto s=EvaluateSeaNuclearWave(a,x,z);r.height+=s.height;r.slopeX+=s.slopeX;r.slopeZ+=s.slopeZ;r.foam=max(r.foam,s.foam);r.load=max(r.load,s.load);}CompressSeaNuclearWaveSample(r);return r;}
static SeaNuclearWaveSample sample(const vector<SeaNuclearWave>&w,float x,float z){constexpr float bound=1600.f;float gx=(x+bound)/32,gz=(z+bound)/32;if(!(gx>=0&&gz>=0&&gx<100&&gz<100))return exact(w,x,z);float left=floor(gx),bottom=floor(gz),u=gx-left,v=gz-bottom;float xx=left*32-bound,zz=bottom*32-bound;auto a=exact(w,xx,zz),b=exact(w,xx+32,zz),c=exact(w,xx,zz+32),d=exact(w,xx+32,zz+32);auto mix=[&](float aa,float bb,float cc,float dd){return (aa*(1-u)+bb*u)*(1-v)+(cc*(1-u)+dd*u)*v;};SeaNuclearWaveSample r{mix(a.height,b.height,c.height,d.height),mix(a.slopeX,b.slopeX,c.slopeX,d.slopeX),mix(a.slopeZ,b.slopeZ,c.slopeZ,d.slopeZ),mix(a.foam,b.foam,c.foam,d.foam),mix(a.load,b.load,c.load,d.load)};float ex=min(gx,100-gx),ez=min(gz,100-gz),e=min(ex,ez);if(e>=4)return r;auto q=exact(w,x,z);float t=clamp(e*.25f,0.f,1.f),k=t*t*(3-2*t),grad=6*t*(1-t)/128,corr=(r.height-q.height)*grad;float dx=ex<=ez?(gx<50?corr:-corr):0,dz=ez<ex?(gz<50?corr:-corr):0;r.slopeX=q.slopeX*(1-k)+r.slopeX*k+dx;r.slopeZ=q.slopeZ*(1-k)+r.slopeZ*k+dz;r.height=q.height*(1-k)+r.height*k;r.foam=q.foam*(1-k)+r.foam*k;r.load=q.load*(1-k)+r.load*k;return r;}
int main(){vector<SeaNuclearWave>w;for(int i=0;i<4;i++){SeaNuclearWave q{1300.f+i*80,50.f*i,0,0,true,1};q.Advance(4+i*.3f);w.push_back(q);}float maxh=0,maxs=0,maxf=0;for(float boundary:{-1600.f,-1472.f,1472.f,1600.f})for(float z:{-35.f,0.f,35.f}){auto a=sample(w,boundary-.01f,z),b=sample(w,boundary+.01f,z);maxh=max(maxh,abs(a.height-b.height));maxs=max(maxs,hypotf(a.slopeX-b.slopeX,a.slopeZ-b.slopeZ));maxf=max(maxf,abs(a.foam-b.foam));}printf("edge_separation=0.02m height_max_delta=%.8f slope_max_delta=%.8f foam_max_delta=%.8f\n",maxh,maxs,maxf);}
